use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let jobs = input.as_array().unwrap();
    let mut indices = Vec::new();
    let mut quantum = input.as_integer().unwrap();

    for (index, job) in jobs.iter().enumerate() {
        if job.is_u64() {
            indices.push(index as i64);
        } else {
            panic!("All job amounts must be nonnegative integers.");
        }
    }

    while quantum > 0 {
        let mut next_indices = Vec::new();
        for &index in &indices {
            let next_index = (index + quantum) % indices.len();
            next_indices.push(next_index);
        }
        indices = next_indices;
        quantum -= 1;
    }

    indices.sort_unstable();
    serde_json::Value::Array(indices)
}
